import com.androidhit.lumadrift.engine.*;import java.security.*;import java.nio.charset.*;
public final class LegacyContentFingerprint{
static String layout(Level l){StringBuilder s=new StringBuilder().append(l.number).append('|').append(l.chapter).append('|').append(l.size).append('|').append(l.initialGateMask).append('|').append(l.seed).append('|').append(l.isEvent);for(Tile t:l.tiles)s.append(';').append(t.id).append(',').append(t.row).append(',').append(t.col).append(',').append(t.direction).append(',').append(t.switchMask);for(int n:l.solution)s.append('/').append(n);for(Barrier b:l.barriers)s.append('@').append(b.row).append(',').append(b.col).append(',').append(b.keyTileId);return s.toString();}
public static void main(String[]args)throws Exception{for(char f:new char[]{'C','R','B','Q','G','H','P','E'}){MessageDigest d=MessageDigest.getInstance("SHA-256");int total=f=='G'?1000:f=='P'?6:f=='E'?4:240;for(int n=1;n<=total;n++){Level l;String code;int mode=4;switch(f){case'C':l=LevelCatalog.get(n);code=ChallengeCode.encodeCampaign(n);break;case'R':l=LevelCatalog.remix(n);code=ChallengeCode.encodeRemix(n);break;case'B':l=BalancedCatalog.legacyGet(n);code=ChallengeCode.encodeBalanced(n);mode=0;break;case'Q':l=BalancedCatalog.legacyRemix(n);code=ChallengeCode.encodeBalancedRemix(n);mode=3;break;case'G':l=BalancedCatalog.getV2(n);code=ChallengeCode.encodeBalancedV2(n);mode=0;break;case'H':l=BalancedCatalog.remixV2(n);code=ChallengeCode.encodeBalancedRemixV2(n);mode=3;break;case'P':l=SealedCatalog.get(n);code=ChallengeCode.encodeSealed(n);break;default:long seed=new long[]{0,1,123,Long.MAX_VALUE}[n-1];l=LevelCatalog.event(seed);code=ChallengeCode.encodeEvent(seed);mode=1;}MoveBudget b=(f=='B'||f=='Q')?MoveBudget.startLegacy(mode,l):MoveBudget.start(mode,l);d.update((layout(l)+"|"+code+"|"+b.base()+"|"+b.mistakeAllowance()+"|"+b.policyVersion()+"\n").getBytes(StandardCharsets.UTF_8));}System.out.print(f+" ");for(byte b:d.digest())System.out.printf("%02x",b);System.out.println();}}
}
